function sound(kind='tap'){if(!settings.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=sound.context??=new C();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(kind==='roll'?420:660,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='roll'?180:880,ctx.currentTime+.12);g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.17);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.18);}catch{}}
const isHuman=()=>state.current===0&&!busy&&!networkPending&&(!onlineMode||roomConnection?.connected);
