const costStateText=cost=>{const missing=Object.fromEntries(Object.entries(cost).map(([r,n])=>[r,Math.max(0,n-state.players[0].resources[r])]).filter(([,n])=>n>0));return costText(cost)+(Object.keys(missing).length?'；还缺 '+costText(missing):'；材料已齐备');};
function diceMarkup(value){if(value===null)return `<span class="dice unrolled" aria-label="尚未掷骰"><b>?</b></span>`;const dots={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]}[value];return `<span class="dice" aria-label="${value} 点">${Array.from({length:9},(_,i)=>`<i class="${dots.includes(i)?'on':''}"></i>`).join('')}</span>`;}
function render(){const declined=!onlineMode&&declineUnpayableOffer(state,0);renderBoard();renderPlayers();renderTurn();renderHand();renderActivity();save();syncOffer();if(declined)toast('已自动婉拒一笔你目前无法支付的报价');scheduleAI();if(state.phase==='over'&&!winnerShown){winnerShown=true;setTimeout(showWinner,350);}if((state.phase==='discard'&&state.discardRequired[0]>0)||(state.phase==='victim'&&state.current===0))ensureInterrupt();renderTutorial();}
