  out+='<g filter="url(#island-shadow)">';
  for(const t of state.tiles){const pts=t.vertices.map(i=>`${state.vertices[i].x.toFixed(1)},${state.vertices[i].y.toFixed(1)}`).join(' ');const side=t.vertices.map(i=>`${state.vertices[i].x.toFixed(1)},${(state.vertices[i].y+10).toFixed(1)}`).join(' ');out+=`<polygon points="${side}" fill="${PALETTE[t.type].side}" stroke="#8e6d3c" stroke-width="1" stroke-linejoin="round"/>`;}
  const active=state.dice&&state.phase!=='roll'?state.dice[0]+state.dice[1]:null;
  for(const t of state.tiles){const pts=t.vertices.map(i=>`${state.vertices[i].x.toFixed(1)},${state.vertices[i].y.toFixed(1)}`).join(' ');const hot=t.number===6||t.number===8,isActive=active===t.number&&t.id!==state.robber;const canRob=isHuman()&&state.phase==='robber'&&t.id!==state.robber;out+=`<g class="terrain ${isActive?'active':''} ${canRob?'robber-target':''}" data-tile="${t.id}" ${canRob?`role="button" tabindex="0" aria-label="将强盗移动到${LABEL[t.type]||'沙漠'}${t.number||''}"`:''}><title>${LABEL[t.type]||'沙漠'}${t.number?' / '+t.number+' 点':''}${t.id===state.robber?' / 强盗封锁':''}</title><polygon class="top" points="${pts}" fill="${PALETTE[t.type].top}"/><g class="terrain-art" transform="translate(${t.x} ${t.y-8})">${terrainArt(t.type)}</g>`;
    if(t.number){const n=6-Math.abs(7-t.number);out+=`<g transform="translate(${t.x} ${t.y+28})"><circle cy="2" r="15.5" fill="#78815c" opacity=".15"/><circle r="15.5" fill="#f7e5b7" stroke="#c9ab70" stroke-width="1"/><text class="number ${hot?'hot':''}" text-anchor="middle" y="4">${t.number}</text><g class="pips ${hot?'hot':''}">${Array.from({length:n},(_,i)=>`<circle cx="${(i-(n-1)/2)*3}" cy="10" r=".85"/>`).join('')}</g></g>`;}out+='</g>';}
  out+='</g>';
  for(const [portId,port] of state.ports.entries()){const label=port.type==='any'?'通用港':LABEL[port.type]+'港',ratio=port.type==='any'?'3:1':'2:1',icon=port.type==='any'?'⚓':RES_ICON[port.type];out+=portMarkup(state,port,portId,{label,ratio,icon});}
  for(const e of state.edges){if(e.owner===null)continue;const a=state.vertices[e.a],b=state.vertices[e.b];out+=`<g aria-hidden="true"><line x1="${a.x}" y1="${a.y+3}" x2="${b.x}" y2="${b.y+3}" stroke="#4a513c" stroke-opacity=".22" stroke-width="9" stroke-linecap="round"/><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#fff8e5" stroke-width="9" stroke-linecap="round"/><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${state.players[e.owner].color}" stroke-width="6" stroke-linecap="round"/></g>`;}
