 modal(counter?'给出你的还价':'让资源各得其所',counter?'修改双方的资源组合，再交给对方决定。':'银行按港口比率兑换；居民之间可以交换多种资源。',`${counter?'':`<div class="segmented"><button data-action="trade-tab" data-tab="bank" class="${tab==='bank'?'active':''}">银行与港口</button><button data-action="trade-tab" data-tab="player" class="${tab==='player'?'active':''}">居民交易</button></div>`}${body}<p id="trade-info" class="trade-info"></p><div class="inline-error" id="trade-error" role="status"></div><button class="primary-button" data-action="confirm-trade">${tab==='bank'?'确认兑换':counter?'提出还价':'发出报价'}</button><div id="trade-result" class="trade-result" role="status"></div>`,'trade');if(preset){$$('[data-trade-side]').forEach(input=>input.readOnly=true);$('#trade-who').disabled=true;}updateTradeInfo();
