 lastOfferId=o.id;const recipient=tradeRecipient(o),other=o.from===0?o.with:o.from,give=o.from===0?o.give:o.get,get=o.from===0?o.get:o.give,canAccept=canPay(state.players[0],give),waiting=recipient!==0;
 modal(waiting?'报价已送出':`${state.players[other].name}${o.proposedBy===o.from?'向你提出交易':'给出了还价'}`,waiting?'等待对方接受、拒绝或还价。':'资源交换只会在双方同意后发生。',`<div class="offer-summary"><div><span>你付出</span><strong>${packageText(give)}</strong></div><span class="offer-arrow">⇄</span><div><span>你获得</span><strong>${packageText(get)}</strong></div></div>${myResourcesMarkup(give)}${!waiting&&!canAccept?'<p class="inline-error">你目前没有足够的资源支付这笔交易。</p>':''}<div class="modal-actions">${waiting?'<button class="outline-button" data-action="cancel-offer">撤回报价</button>':`<button class="outline-button" data-action="reject-offer">拒绝</button><button class="outline-button" data-action="counter-offer">还价</button><button class="primary-button" data-action="accept-offer" ${canAccept?'':'disabled'}>接受</button>`}</div>`,'offer');
