 if(!tutorial){tutorialLayer?.remove();tutorialLayer=null;return;}
 const old=tutorial.step,steps=getGuideSteps(tutorial.lesson);tutorial.step=advanceGuide(old,state,{choice:setupChoice,modal:modalType,mode,discarded,picked:pickedResources},tutorial.lesson);
