 if(changed||!tutorialLayer.firstChild){tutorialLayer.innerHTML=`<div class="tutorial-highlight" aria-hidden="true"></div><section class="tutorial-card" aria-live="polite"><div class="tutorial-card-head"><span>${LESSON_INFO[tutorial.lesson].name} · ${step.group}/${totalGroups}</span><button data-action="tutorial-exit" class="tutorial-exit">退出教学</button></div><div class="tutorial-progress" aria-hidden="true">${Array.from({length:totalGroups},(_,i)=>`<i class="${i<step.group?'done':''}"></i>`).join('')}</div><h2>${step.title}</h2><p>${step.text}</p>${step.ack?`<button class="primary-button" data-action="tutorial-next">${step.ack}</button>${step.done?'<button class="tutorial-more" data-action="tutorial-menu">学习其他内容</button>':''}`:`<div class="tutorial-cue">${step.waiting?'<i class="tutorial-spinner"></i> 请稍等':'↖ 点击高亮处继续'}</div>`}</section>`;lastGuideStep=tutorial.step;}
